/* ============================================================
   imagens.js — as imagens dos gatinhos, embutidas (base64)
   GERADO a partir de img/*.png.

   Por que embutir? As imagens são usadas como máscara (o desenho
   pega a cor do tema). O navegador BLOQUEIA máscaras carregadas de
   arquivos soltos quando o index.html é aberto direto do disco
   (file://), e aí as imagens não apareceriam. Embutidas aqui,
   vão funcionar de qualquer jeito. */

const IMAGENS = {
  "dormindo": "data:image/png;base64,",
  "z1": "data:image/png;base64,",
  "z2": "data:image/png;base64,",
  "z3": "data:image/png;base64,",
  "notebook": "data:image/png;base64,",
  "canto-verde": "data:image/png;base64,",
  "canto-clara": "data:image/png;base64,",
  "canto-preto": "data:image/png;base64,",
  "canto-rosa": "data:image/png;base64,",
};

(function () {
  const estilo = document.createElement("style");
  estilo.id = "imagens-gatinhos";
  estilo.textContent = ":root{" + Object.keys(IMAGENS).map(n => `--img-${n}:url("${IMAGENS[n]}");`).join("") + "}";
  document.head.appendChild(estilo);
})();
